def icon(name,size=18):
    return f'<svg width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" xmlns="http://www.w3.org/2000/svg">{icons.get(name,icons["code"])}</svg>'
def button(text,kind='',sym=None):
    return f'<div class="button {kind}">{icon(sym,16) if sym else ""}<span>{text}</span></div>'
def chip(text,tone='purple'):
    return f'<span class="chip {tone}">{text}</span>'
def field(label,value,unit='',wide=False):
    return f'<div class="field {"wide" if wide else ""}"><div class="label">{label}</div><div class="input"><span>{value}</span><span class="unit">{unit}</span></div></div>'
def line():return '<div class="line"></div>'
