def shell(title,active,inner,tab=None,headright=''):
    nav=''
    groups=[('工作台',[('device','设备','devices'),('folder','文件与产物','files')]),('深度调试',[('performance','性能与调用栈','performance'),('code','Frida','frida'),('automation','自动化','automation'),('code','终端','terminal')]),('扩展创作',[('settings','AI 助手','ai'),('performance','数据分析','analysis')]),('工坊',[('log','任务与日志','tasks'),('folder','市场','market'),('settings','设置','settings')])]
    for name,items in groups:
        nav+=f'<div class="group">{name}</div>'
        for sym,label,key in items: nav+=f'<div class="nav {"active" if key==active else ""}">{icon(sym)}<span>{label}</span></div>'
    tabs=''
    if tab is not None:
        opts=[('device','device','设备步骤'),('desktop','mouse','桌面操作'),('trace','record','输入录制与回放')]
        tabs='<div class="tabs">'+''.join(f'<div class="tab {"active" if key==tab else ""}">{icon(sym,16)}{label}</div>' for key,sym,label in opts)+'</div>'
    return f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><style>{CSS}</style></head><body><div class="screen"><aside class="sidebar"><div class="brand"><div class="brandmark">{icon('automation',20)}</div>DeviceForge</div>{nav}<div class="sidebarfoot"><div class="row gap8">{icon('plus',14)}插件模块</div></div></aside><main class="main"><div class="topbar"><div class="row gap8"><span>工作空间</span>{icon('chevron',12)}<span style="color:#3F4757">{title}</span></div><div class="row gap16"><span class="devicepill"><span class="platform">A</span>SM-G991U <i class="dot"></i>{icon('chevron',12)}</span>{icon('help',17)}</div></div><div class="content"><div class="pagehead"><h1>{title}</h1>{headright}</div>{tabs}{inner}</div><div class="footer"><span class="row gap8"><i class="dot"></i>服务已连接 <span class="mono">127.0.0.1:7031</span></span><span>设备工坊 <span class="mono">DeviceForge</span></span></div></main></div></body></html>'''

